// ---- short, speakable ids: REM-1042 instead of CGPE-REM-MRUL1EWD-90 ----
// Old long ids stay as they are; only newly created records get the short form.
var SHORT = { reminderId: ['REM', 1000], leadId: ['LED', 1000], prospectId: ['PRO', 1000] };
var recCount = 0;
try { recCount = $('Count Short Recs').all().filter(function (i) { return i.json && Object.keys(i.json).length; }).length; } catch (e) { recCount = 0; }
Object.keys(SHORT).forEach(function (field) {
  if (!Object.prototype.hasOwnProperty.call(doc, field)) { return; }
  var cur = String(doc[field] || '');
  if (/^[A-Z]{3}-[0-9]+$/.test(cur)) { return; }        // already short
  var conf = SHORT[field];
  doc[field] = conf[0] + '-' + (conf[1] + recCount + 1);
});


